-- Part Sorter (436188) ships without his two hard-mode drops; append them
-- to his live lootdrop (resolve the drop id from his table).
SELECT le.lootdrop_id, x.item_id, 1, 0, x.ch FROM loottable_entries le,
(SELECT 101609 item_id, 15 ch UNION ALL SELECT 101617, 15) x
WHERE le.loottable_id = 436188
  AND NOT EXISTS (SELECT 1 FROM lootdrop_entries de WHERE de.lootdrop_id = le.lootdrop_id AND de.item_id = x.item_id);

